GTKNoCSDMenuShown:
bool GTKNoCSDMenuShown(GtkWidget *Widget) {
	// Whether the widget is visible and no container keeps it hidden. At
	// realize nothing is mapped yet, so a hidden stack page is also visible,
	// but its container clears child-visible on it or on an ancestor

	if (!o_gtk_widget_is_visible(Widget)) {
		return false;
	}

	// WARNING: Own call
	for (GtkWidget *Current = Widget; Current != NULL;
		Current = gtk_widget_get_parent(Current)) {
		if (!o_gtk_widget_get_child_visible(Current)) {
			return false;
		}
	}

	return true;
}

GTKNoCSDMenuReachableItems:
int GTKNoCSDMenuReachableItems(GMenuModel *Model, int Depth) {
	// Count items anywhere in the menu that use application or window actions

	const char *Links[] = {"section", "submenu"};
	int Count = 0;
	gint Items = o_g_menu_model_get_n_items(Model);
	for (gint Index = 0; Index < Items; ++Index) {
		GVariant *Action = o_g_menu_model_get_item_attribute_value(Model,
				Index, "action", G_VARIANT_TYPE_STRING);
		if (Action != NULL) {
			const char *Name = o_g_variant_get_string(Action, NULL);
			if (strncmp(Name, "app.", 4) == 0 ||
				strncmp(Name, "win.", 4) == 0) {
				++Count;
			}
			o_g_variant_unref(Action);
		}

		for (size_t Link = 0; Link < 2 && Depth < 16; ++Link) {
			GMenuModel *Child = o_g_menu_model_get_item_link(Model, Index,
					Links[Link]);
			if (Child != NULL) {
				Count += GTKNoCSDMenuReachableItems(Child, Depth + 1);
				o_g_object_unref((GObject *) Child);
			}
		}
	}

	return Count;
}

GTKNoCSDMenuAddCandidate:
void GTKNoCSDMenuAddCandidate(struct GTKNoCSDMenuCandidates *Candidates,
	GtkWidget *Owner, GMenuModel *Model, bool Primary) {
	// Save a menu with what decides whether it is the main menu

	if (Candidates->Count == sizeof(Candidates->List) /
		sizeof(Candidates->List[0])) {
		return;
	}

	struct GTKNoCSDMenuCandidate *Candidate =
		&Candidates->List[Candidates->Count++];
	Candidate->Owner = Owner;
	Candidate->Model = Model;
	Candidate->Shown = GTKNoCSDMenuShown(Owner);
	Candidate->Primary = Primary;
	Candidate->Score = GTKNoCSDMenuReachableItems(Model, 0);
}

GTKNoCSDMenuCollect:
void GTKNoCSDMenuCollect(GtkWidget *Widget, int Depth,
	struct GTKNoCSDMenuCandidates *Candidates) {
	// Collect every menu button and popover menu bar of a widget tree

	if (Widget == NULL || 32 < Depth) {
		return;
	}

	if (GTKNoCSDGtkMenuButton((GObject *) Widget)) {
		GtkMenuButton *Button = (GtkMenuButton *) Widget;
		GMenuModel *Model = o_gtk_menu_button_get_menu_model(Button);

		// A menu set with gtk_menu_button_set_popover is still reachable
		// through the popover, when that is a GtkPopoverMenu (Yelp)
		if (Model == NULL) {
			GtkPopover *Popover = o_gtk_menu_button_get_popover(Button);
			if (GTKNoCSDGtkPopoverMenu((GObject *) Popover)) {
				Model = o_gtk_popover_menu_get_menu_model(
					(GtkPopoverMenu *) Popover);
			}
		}

		if (Model != NULL) {
			GTKNoCSDMenuAddCandidate(Candidates, Widget, Model,
				o_gtk_menu_button_get_primary != NULL &&
				o_gtk_menu_button_get_primary(Button));
		}
	}

	if (GTKNoCSDGtkPopoverMenuBar((GObject *) Widget)) {
		GMenuModel *Model = o_gtk_popover_menu_bar_get_menu_model(
			(GtkPopoverMenuBar *) Widget);
		if (Model != NULL) {
			GTKNoCSDMenuAddCandidate(Candidates, Widget, Model, false);
		}
	}

	// WARNING: Own call
	for (GtkWidget *Child = gtk_widget_get_first_child(Widget);
		Child != NULL; Child = o_gtk_widget_get_next_sibling(Child)) {
		GTKNoCSDMenuCollect(Child, Depth + 1, Candidates);
	}
}

GTKNoCSDMenuFind:
GMenuModel *GTKNoCSDMenuFind(GtkWindow *Window, GtkWidget **Owner) {
	// Find the main menu of a window. A window often has several menu buttons,
	// so the one that is shown wins, then the primary one (the one F10 opens),
	// then the one with most application and window actions, then the first

	struct GTKNoCSDMenuCandidates Candidates = {0};

	// The title bar is not in the child tree. Some keep the header bar in the
	// content (Yelp), so both are searched
	// WARNING: Own call
	GTKNoCSDMenuCollect(gtk_window_get_titlebar(Window), 0, &Candidates);

	// WARNING: Own call
	GTKNoCSDMenuCollect(gtk_window_get_child(Window), 0, &Candidates);
	if (Candidates.Count == 0) {
		return NULL;
	}

	size_t Best = 0;
	for (size_t Index = 1; Index < Candidates.Count; ++Index) {
		struct GTKNoCSDMenuCandidate *Candidate = &Candidates.List[Index];
		struct GTKNoCSDMenuCandidate *Current = &Candidates.List[Best];
		if (Candidate->Shown != Current->Shown) {
			Best = Candidate->Shown ? Index : Best;
		} else if (Candidate->Primary != Current->Primary) {
			Best = Candidate->Primary ? Index : Best;
		} else if (Current->Score < Candidate->Score) {
			Best = Index;
		}
	}

	*Owner = Candidates.List[Best].Owner;
	return Candidates.List[Best].Model;
}

GTKNoCSDMenuLabel:
gchar *GTKNoCSDMenuLabel(GtkApplication *Application) {
	// Name of the menu: the name of the desktop entry, which is what panels
	// show next to it, otherwise the application name

	const char *Identifier = o_g_application_get_application_id(
		(GApplication *) Application);
	if (Identifier != NULL) {
		gchar *DesktopEntry = o_g_strconcat(Identifier, ".desktop", NULL);
		GAppInfo *Information = o_g_desktop_app_info_new(DesktopEntry);
		o_g_free(DesktopEntry);
		if (Information != NULL) {
			const char *Name = o_g_app_info_get_name(Information);
			gchar *Label = Name != NULL ? o_g_strdup(Name) : NULL;
			o_g_object_unref((GObject *) Information);
			if (Label != NULL) {
				return Label;
			}
		}
	}

	const char *Name = o_g_get_application_name();
	return o_g_strdup(Name != NULL ? Name : "Menu");
}

GTKNoCSDMenuKey:
gchar *GTKNoCSDMenuKey(const char *Kind, const char *Name) {
	// Name of the data saved on a widget for one of its class actions

	return o_g_strconcat("GTKNoCSDMenu", Kind, ":", Name, NULL);
}

GTKNoCSDMenuProxyActivate:
void GTKNoCSDMenuProxyActivate(G_GNUC_UNUSED GSimpleAction *Action,
	GVariant *Parameter, gpointer Data) {
	// Activate the class action from the menu's owner

	struct GTKNoCSDMenuProxy *Proxy = Data;
	if (Proxy->Owner != NULL) {
		o_gtk_widget_activate_action_variant(Proxy->Owner, Proxy->Name,
			Parameter);
	}
}

GTKNoCSDMenuProxyFree:
void GTKNoCSDMenuProxyFree(gpointer Data, G_GNUC_UNUSED GClosure *Closure) {
	// Free a stand-in when its action is finalized

	struct GTKNoCSDMenuProxy *Proxy = Data;
	if (Proxy->Owner != NULL) {
		o_g_object_remove_weak_pointer((GObject *) Proxy->Owner,
			(gpointer *) &Proxy->Owner);
	}
	if (Proxy->Holder != NULL) {
		gchar *Key = GTKNoCSDMenuKey("Proxy", Proxy->Name);
		o_g_object_set_data((GObject *) Proxy->Holder, Key, NULL);
		o_g_free(Key);
		o_g_object_remove_weak_pointer((GObject *) Proxy->Holder,
			(gpointer *) &Proxy->Holder);
	}
	o_g_free(Proxy->Name);
	free(Proxy);
}

GTKNoCSDMenuFindClassAction:
GtkWidget *GTKNoCSDMenuFindClassAction(GtkWidget *Widget, const char *Name,
	const GVariantType **ParameterType, const char **Property) {
	// Find the widget, the given one or an ancestor, whose class has the
	// action, with the property of a property action

	// WARNING: Own call
	for (; Widget != NULL; Widget = gtk_widget_get_parent(Widget)) {
		GtkWidgetClass *Class =
			(GtkWidgetClass *) ((GTypeInstance *) Widget)->g_class;
		GType Owner;
		const char *ActionName, *PropertyName;
		const GVariantType *Type;
		for (guint Index = 0; o_gtk_widget_class_query_action(Class, Index,
			&Owner, &ActionName, &Type, &PropertyName); ++Index) {
			if (strcmp(ActionName, Name) == 0) {
				*ParameterType = Type;
				*Property = PropertyName;
				return Widget;
			}
		}
	}

	return NULL;
}

GTKNoCSDMenuPropertyState:
GVariant *GTKNoCSDMenuPropertyState(GObject *Object, GParamSpec *Property) {
	// The state of a property action, as GTK derives it from the property type

	GValue Value = G_VALUE_INIT;
	GVariant *State = NULL;
	GType Type = Property->value_type;
	o_g_value_init(&Value, Type);
	o_g_object_get_property(Object, Property->name, &Value);

	if (Type == G_TYPE_BOOLEAN) {
		State = o_g_variant_new_boolean(o_g_value_get_boolean(&Value));
	} else if (Type == G_TYPE_INT) {
		State = o_g_variant_new_int32(o_g_value_get_int(&Value));
	} else if (Type == G_TYPE_UINT) {
		State = o_g_variant_new_uint32(o_g_value_get_uint(&Value));
	} else if (Type == G_TYPE_DOUBLE) {
		State = o_g_variant_new_double(o_g_value_get_double(&Value));
	} else if (Type == G_TYPE_FLOAT) {
		State = o_g_variant_new_double(o_g_value_get_float(&Value));
	} else if (Type == G_TYPE_STRING) {
		const char *String = o_g_value_get_string(&Value);
		State = o_g_variant_new_string(String != NULL ? String : "");
	} else if (o_g_type_fundamental(Type) == G_TYPE_ENUM) {
		GEnumClass *Class = o_g_type_class_ref(Type);
		GEnumValue *Enumeration = o_g_enum_get_value(Class,
				o_g_value_get_enum(&Value));
		State = o_g_variant_new_string(Enumeration != NULL ?
				Enumeration->value_nick : "");
		o_g_type_class_unref(Class);
	}

	o_g_value_unset(&Value);
	return State;
}

GTKNoCSDMenuPropertyNotified:
void GTKNoCSDMenuPropertyNotified(GObject *Holder, GParamSpec *Property,
	gpointer Action) {
	// Follow the property of a property action

	GVariant *State = GTKNoCSDMenuPropertyState(Holder, Property);
	if (State != NULL) {
		o_g_simple_action_set_state(Action, State);
	}
}

GTKNoCSDMenuProxyChangeState:
void GTKNoCSDMenuProxyChangeState(GSimpleAction *Action, GVariant *Value,
	gpointer Data) {
	// A state change asked over D-Bus goes to the property like activation.
	// The new state comes back through notify

	struct GTKNoCSDMenuProxy *Proxy = Data;
	if (Proxy->Owner == NULL) {
		return;
	}

	if (!o_g_variant_is_of_type(Value, G_VARIANT_TYPE_BOOLEAN)) {
		o_gtk_widget_activate_action_variant(Proxy->Owner, Proxy->Name,
			Value);
		return;
	}

	GVariant *Current = o_g_action_get_state((GAction *) Action);
	bool Differs = Current == NULL ||
		o_g_variant_get_boolean(Current) != o_g_variant_get_boolean(Value);
	if (Current != NULL) {
		o_g_variant_unref(Current);
	}
	if (Differs) {
		o_gtk_widget_activate_action_variant(Proxy->Owner, Proxy->Name, NULL);
	}
}

GTKNoCSDMenuProxyFor:
gchar *GTKNoCSDMenuProxyFor(const char *Name, GtkWidget *Owner,
	GActionMap *Map) {
	// The action name the exported item uses: a stand-in in the window's
	// actions for a class action, otherwise NULL to keep the name

	const GVariantType *ParameterType = NULL;
	const char *Property = NULL;
	GtkWidget *Holder = GTKNoCSDMenuFindClassAction(Owner, Name,
			&ParameterType, &Property);
	if (Holder == NULL) {
		return NULL;
	}

	// No dots: the whole name after win. is one action name
	gchar *Local = o_g_strconcat("gtk-nocsd-", Name, NULL);
	for (gchar *Character = Local; *Character != '\0'; ++Character) {
		if (*Character == '.') {
			*Character = '-';
		}
	}

	if (o_g_action_map_lookup_action(Map, Local) == NULL) {
		GParamSpec *Specification = NULL;
		GVariant *State = NULL;
		if (Property != NULL) {
			Specification = o_g_object_class_find_property(
				(GObjectClass *) ((GTypeInstance *) Holder)->g_class,
				Property);
			if (Specification != NULL) {
				State = GTKNoCSDMenuPropertyState((GObject *) Holder,
						Specification);
			}

			// A property type GTK itself does not turn into an action
			if (State == NULL) {
				o_g_free(Local);
				return NULL;
			}
		}

		struct GTKNoCSDMenuProxy *Proxy = calloc(1,
				sizeof(struct GTKNoCSDMenuProxy));
		if (Proxy == NULL) {
			o_g_free(Local);
			return NULL;
		}
		Proxy->Owner = Owner;
		Proxy->Holder = Holder;
		Proxy->Name = o_g_strdup(Name);
		o_g_object_add_weak_pointer((GObject *) Owner,
			(gpointer *) &Proxy->Owner);
		o_g_object_add_weak_pointer((GObject *) Holder,
			(gpointer *) &Proxy->Holder);

		GSimpleAction *Action = State != NULL ?
			o_g_simple_action_new_stateful(Local, ParameterType, State) :
			o_g_simple_action_new(Local, ParameterType);
		o_g_signal_connect_data(Action, "activate",
			(GCallback) GTKNoCSDMenuProxyActivate, Proxy,
			GTKNoCSDMenuProxyFree, 0);
		if (State != NULL) {
			o_g_signal_connect_data(Action, "change-state",
				(GCallback) GTKNoCSDMenuProxyChangeState, Proxy, NULL, 0);
			gchar *Signal = o_g_strconcat("notify::", Specification->name,
					NULL);
			o_g_signal_connect_object(Holder, Signal,
				(GCallback) GTKNoCSDMenuPropertyNotified, Action, 0);
			o_g_free(Signal);
		}

		// Start from what the application has set so far
		gchar *Key = GTKNoCSDMenuKey("Enabled", Name);
		o_g_simple_action_set_enabled(Action,
			o_g_object_get_data((GObject *) Holder, Key) !=
			GINT_TO_POINTER(2));
		o_g_free(Key);
		Key = GTKNoCSDMenuKey("Proxy", Name);
		o_g_object_set_data((GObject *) Holder, Key, Action);
		o_g_free(Key);

		o_g_action_map_add_action(Map, (GAction *) Action);
		o_g_object_unref((GObject *) Action);
	}

	gchar *Exported = o_g_strconcat("win.", Local, NULL);
	o_g_free(Local);
	return Exported;
}

GTKNoCSDMenuClean:
GMenuModel *GTKNoCSDMenuClean(GMenuModel *Model, int Depth, GtkWidget *Owner,
	GActionMap *Map) {
	// Copy the menu without items that embed a widget, which cannot cross
	// D-Bus (Yelp's zoom), and without sections left empty by that. Class
	// actions are replaced with their stand-ins

	const char *Links[] = {"section", "submenu"};
	GMenu *Menu = o_g_menu_new();
	gint Items = o_g_menu_model_get_n_items(Model);
	for (gint Index = 0; Index < Items; ++Index) {
		GVariant *Custom = o_g_menu_model_get_item_attribute_value(Model,
				Index, "custom", NULL);
		if (Custom != NULL) {
			o_g_variant_unref(Custom);
			continue;
		}

		GMenuItem *Item = o_g_menu_item_new_from_model(Model, Index);
		GVariant *Action = Map == NULL ? NULL :
			o_g_menu_model_get_item_attribute_value(Model, Index, "action",
				G_VARIANT_TYPE_STRING);
		if (Action != NULL) {
			gchar *Exported = GTKNoCSDMenuProxyFor(
				o_g_variant_get_string(Action, NULL), Owner, Map);
			if (Exported != NULL) {
				o_g_menu_item_set_attribute_value(Item, "action",
					o_g_variant_new_string(Exported));
				o_g_free(Exported);
			}
			o_g_variant_unref(Action);
		}

		bool Keep = true;
		for (size_t Link = 0; Link < 2 && Depth < 16; ++Link) {
			GMenuModel *Child = o_g_menu_model_get_item_link(Model, Index,
					Links[Link]);
			if (Child == NULL) {
				continue;
			}

			GMenuModel *Cleaned = GTKNoCSDMenuClean(Child, Depth + 1, Owner,
					Map);
			o_g_object_unref((GObject *) Child);
			if (o_g_menu_model_get_n_items(Cleaned) == 0) {
				Keep = false;
			} else {
				o_g_menu_item_set_link(Item, Links[Link], Cleaned);
			}
			o_g_object_unref((GObject *) Cleaned);
		}

		if (Keep) {
			o_g_menu_append_item(Menu, Item);
		}
		o_g_object_unref((GObject *) Item);
	}

	return (GMenuModel *) Menu;
}

GTKNoCSDMenuShellChanged:
void GTKNoCSDMenuShellChanged(GObject *Settings,
	G_GNUC_UNUSED GParamSpec *Property, gpointer Application) {
	// Remove the menubar when the shell no longer shows it

	gboolean ShellShowsMenubar = TRUE;
	o_g_object_get(Settings, "gtk-shell-shows-menubar", &ShellShowsMenubar,
		NULL);
	if (!ShellShowsMenubar && GTKNoCSDMenubar != NULL &&
		o_gtk_application_get_menubar(Application) == GTKNoCSDMenubar) {
		o_gtk_application_set_menubar(Application, NULL);
	}
}

GTKNoCSDMenuAttach:
void GTKNoCSDMenuAttach(GtkWindow *Window) {
	// Set the main menu of the window as the application's menubar

	// WARNING: Own call
	GtkApplication *Application = gtk_window_get_application(Window);
	if (Application == NULL) {
		return;
	}

	// Only where the shell shows the menubar. Elsewhere it would be in the
	// window, next to the menu it copies
	gboolean ShellShowsMenubar = FALSE;
	o_g_object_get((GObject *) o_gtk_settings_get_default(),
		"gtk-shell-shows-menubar", &ShellShowsMenubar, NULL);
	if (!ShellShowsMenubar) {
		return;
	}

	GMenuModel *Existing = o_gtk_application_get_menubar(Application);
	if (Existing != NULL && Existing != GTKNoCSDMenubar) {
		return;
	}

	GtkWidget *Owner = NULL;
	GMenuModel *Model = GTKNoCSDMenuFind(Window, &Owner);
	if (Model == NULL) {
		return;
	}

	// The menubar belongs to the application, but window actions to the
	// focused window, so another window only needs the stand-ins
	GActionMap *Map = GTKNoCSDGtkApplicatonWindow((GObject *) Window) ?
		(GActionMap *) Window : NULL;
	GMenuModel *Cleaned = GTKNoCSDMenuClean(Model, 0, Owner, Map);
	if (Existing != NULL) {
		o_g_object_unref((GObject *) Cleaned);
		return;
	}

	gchar *Label = GTKNoCSDMenuLabel(Application);
	GMenu *Menubar = o_g_menu_new();
	o_g_menu_append_submenu(Menubar, Label, Cleaned);
	o_g_free(Label);
	o_g_object_unref((GObject *) Cleaned);
	o_gtk_application_set_menubar(Application, (GMenuModel *) Menubar);

	// A withdrawn menubar may still live, it must not clear the new one
	if (GTKNoCSDMenubar != NULL) {
		o_g_object_remove_weak_pointer((GObject *) GTKNoCSDMenubar,
			(gpointer *) &GTKNoCSDMenubar);
	}
	GTKNoCSDMenubar = (GMenuModel *) Menubar;
	o_g_object_add_weak_pointer((GObject *) Menubar,
		(gpointer *) &GTKNoCSDMenubar);
	o_g_object_unref((GObject *) Menubar);

	// Take it back if the shell stops showing it. Otherwise GTK would show it
	// in the window
	if (!GTKNoCSDMenuWatching) {
		GTKNoCSDMenuWatching = true;
		o_g_signal_connect_object(o_gtk_settings_get_default(),
			"notify::gtk-shell-shows-menubar",
			(GCallback) GTKNoCSDMenuShellChanged, Application, 0);
	}
}

GTKNoCSDMenuWindowRealize:
void GTKNoCSDMenuWindowRealize(GtkWidget *Widget) {
	// Realize of GtkWindow. The menu must be set before it

	// GtkApplicationWindow chains up here, it was handled in its own realize
	if (GTKNoCSDApplicationWindowRealize == NULL ||
		!GTKNoCSDGtkApplicatonWindow((GObject *) Widget)) {
		GTKNoCSDMenuAttach((GtkWindow *) Widget);
	}
	if (GTKNoCSDWindowRealize != NULL) {
		GTKNoCSDWindowRealize(Widget);
	}
}

GTKNoCSDMenuApplicationWindowRealize:
void GTKNoCSDMenuApplicationWindowRealize(GtkWidget *Widget) {
	// Realize of GtkApplicationWindow. The menu must be set before it

	GTKNoCSDMenuAttach((GtkWindow *) Widget);
	if (GTKNoCSDApplicationWindowRealize != NULL) {
		GTKNoCSDApplicationWindowRealize(Widget);
	}
}

GTKNoCSDMenuHookClass:
void GTKNoCSDMenuHookClass(GType Type, void(**Original)(GtkWidget *),
	void (*Replacement)(GtkWidget *)) {
	// Replace realize in the class of a window type. The class reference is
	// kept, the class has to live as long as the process anyway

	GtkWidgetClass *Class = o_g_type_class_ref(Type);
	if (Class->realize == GTKNoCSDMenuWindowRealize ||
		Class->realize == GTKNoCSDMenuApplicationWindowRealize) {
		return;
	}
	*Original = Class->realize;
	Class->realize = Replacement;
}

GTKNoCSDGetMenuSymbols:
